/**  A place on the screen a panel snaps to. */
export type OverlayAnchor = "top-left" | "top-center" | "top-right" | "center-left" | "center-right";

/**  One panel of the overlay, each in its own window. */
export type OverlayPanel = 
/**  The next item to buy, and the gold it still needs. */
"next-item" | 
/**  Each side's chance to win, estimated from the item-gold gap. */
"win-probability" | 
/**  Each team's item gold and each lane's gap, while TAB is held. */
"item-value" | 
/**  Our CS per minute, with its curve, and gold per minute. */
"stats" | 
/**  When the dragon, the grubs, the Herald and Baron are next up. */
"objectives" | 
/**
 *  Each lane's item-gold gap on a plate down the TAB scoreboard's middle,
 *  one per row (`scoreboard`).
 */
"lane-gold";

/**
 *  Where the player dragged a panel, as a fraction of the room the screen
 *  leaves around it on each axis: 0 against the left (top) edge, 1 against
 *  the right (bottom) one. So it lands in the same place at any resolution,
 *  and a panel against an edge stays against it whatever size it takes —
 *  its centre would drift off the edge when it grows or shrinks.
 */
export type OverlayPoint = {
	x: number,
	y: number,
};


export type OverlaySettingsInput = {
	/**
	 *  The whole overlay. On by default: it is the app's in-game half, it
	 *  costs nothing, and one shortcut hides it for the game.
	 */
	enabled: boolean,
	/**  When the next item shows; the other panels have their own moment. */
	show: OverlayShow,
	/**  Every panel's size against its natural one. */
	scale: number,
	opacity: number,
	nextItem: PanelSettingsInput,
	winProbability: PanelSettingsInput,
	itemValue: PanelSettingsInput,
	stats: PanelSettingsInput,
	objectives: PanelSettingsInput,
	/**
	 *  Its anchor and custom place are kept but never read: the scoreboard
	 *  places it (`OverlayPanel::on_scoreboard`).
	 */
	laneGold: PanelSettingsInput,
	/**
	 *  The lane-gold plates moved up (negative) or down from where the
	 *  scoreboard's rows are measured to be, in pixels of a 1080p screen, for
	 *  a setup the measure misses (`scoreboard::MAX_NUDGE` either way).
	 */
	scoreboardNudge: number,
};

